import java.sql.*;

class ProductLookup {
    // productName comes from an untrusted HTTP request parameter.
    static boolean productExists(Connection connection, String productName)
            throws SQLException {
        // Fixed: placeholders keep untrusted values separate from SQL syntax.
        String sql = "SELECT id FROM products WHERE name = ?";

        try (PreparedStatement statement = connection.prepareStatement(sql)) {
            // Bind the input as data rather than concatenating it into the query.
            statement.setString(1, productName);

            try (ResultSet results = statement.executeQuery()) {
                return results.next();
            }
        }
    }
}
